const DAY_MS = 86400000;
const DATE_PATTERN = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;

function parseDate(value) {
  if (typeof value !== "string" || value.length !== 10) {
    throw new RangeError("Expected a real calendar date in YYYY-MM-DD form");
  }

  const match = DATE_PATTERN.exec(value);
  if (!match) {
    throw new RangeError("Expected a real calendar date in YYYY-MM-DD form");
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  // Unlike Date.UTC, setUTCFullYear does not remap years 0-99.
  const parsed = new Date(0);
  parsed.setUTCFullYear(year, month - 1, day);

  if (
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() !== month - 1 ||
    parsed.getUTCDate() !== day
  ) {
    throw new RangeError("Expected a real calendar date in YYYY-MM-DD form");
  }

  return parsed.getTime() / DAY_MS;
}

const MIN_DAY = parseDate("0000-01-01");
const MAX_DAY = parseDate("9999-12-31");

function formatDate(day) {
  return new Date(day * DAY_MS).toISOString().slice(0, 10);
}

function weekday(day) {
  // Epoch day 0 (1970-01-01) was Thursday. Normalize negative remainders.
  return (((day + 4) % 7) + 7) % 7;
}

function isWeekday(day) {
  const dayOfWeek = weekday(day);
  return dayOfWeek >= 1 && dayOfWeek <= 5;
}

function makeCalendar(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array of calendar dates");
  }

  const observed = new Set();
  const weekends = [];

  // Reserve every weekday holiday before placing any weekend holiday.
  for (const holiday of holidays) {
    const day = parseDate(holiday);
    if (isWeekday(day)) {
      observed.add(day);
    } else {
      weekends.push(day);
    }
  }

  weekends.sort((a, b) => a - b);

  let lastPlaced = -Infinity;
  for (const day of weekends) {
    const nextMonday = day + (weekday(day) === 6 ? 2 : 1);

    // Targets are nondecreasing, and earlier weekdays are already occupied.
    let candidate = Math.max(nextMonday, lastPlaced + 1);
    while (!isWeekday(candidate) || observed.has(candidate)) {
      candidate += 1;
    }

    observed.add(candidate);
    lastPlaced = candidate;
  }

  return {
    observed,
    sorted: Array.from(observed).sort((a, b) => a - b),
  };
}

function upperBound(sorted, day) {
  let low = 0;
  let high = sorted.length;

  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (sorted[middle] <= day) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

// Counts business days in (start, end], where start <= end.
function countBusinessDays(start, end, sortedHolidays) {
  const distance = end - start;
  let count = Math.floor(distance / 7) * 5;

  for (let offset = 1; offset <= distance % 7; offset += 1) {
    if (isWeekday(start + offset)) {
      count += 1;
    }
  }

  return (
    count -
    (upperBound(sortedHolidays, end) - upperBound(sortedHolidays, start))
  );
}

export function isBusinessDay(date, holidays = []) {
  const day = parseDate(date);
  const calendar = makeCalendar(holidays);
  return isWeekday(day) && !calendar.observed.has(day);
}

export function addBusinessDays(date, n, holidays = []) {
  const start = parseDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer");
  }

  const calendar = makeCalendar(holidays);

  if (n === 0) {
    if (isWeekday(start) && !calendar.observed.has(start)) {
      return date;
    }
    n = 1;
  }

  if (n > 0) {
    if (countBusinessDays(start, MAX_DAY, calendar.sorted) < n) {
      throw new RangeError("Result is outside the YYYY-MM-DD date range");
    }

    // Find the first date at which n business days have been passed.
    let low = start + 1;
    let high = MAX_DAY;

    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if (countBusinessDays(start, middle, calendar.sorted) >= n) {
        high = middle;
      } else {
        low = middle + 1;
      }
    }

    return formatDate(low);
  }

  const target = -n;
  const lastDay = start - 1;

  if (countBusinessDays(MIN_DAY - 1, lastDay, calendar.sorted) < target) {
    throw new RangeError("Result is outside the YYYY-MM-DD date range");
  }

  // Find the last candidate with target business days in [candidate, start).
  let low = MIN_DAY;
  let high = lastDay;

  while (low < high) {
    const middle = Math.floor((low + high + 1) / 2);
    if (
      countBusinessDays(middle - 1, lastDay, calendar.sorted) >= target
    ) {
      low = middle;
    } else {
      high = middle - 1;
    }
  }

  return formatDate(low);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startDay = parseDate(start);
  const endDay = parseDate(end);
  const calendar = makeCalendar(holidays);

  if (startDay <= endDay) {
    return countBusinessDays(startDay, endDay, calendar.sorted);
  }

  const count = countBusinessDays(endDay, startDay, calendar.sorted);
  return count === 0 ? 0 : -count;
}
